CREATE TABLE IF NOT EXISTS sales (order_id TEXT PRIMARY KEY, order_date DATE NOT NULL, customer_id TEXT NOT NULL, product_name TEXT NOT NULL, category TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), unit_price REAL NOT NULL CHECK(unit_price>=0), discount_pct REAL NOT NULL CHECK(discount_pct BETWEEN 0 AND 1), revenue REAL NOT NULL, cost REAL NOT NULL, profit REAL NOT NULL, region TEXT NOT NULL, sales_channel TEXT NOT NULL, customer_segment TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sales_date ON sales(order_date);
CREATE INDEX IF NOT EXISTS idx_sales_customer ON sales(customer_id);
